#!/usr/bin/env python3
"""Paper 4 (The Reach of Suction-Triggered Irrigation and the Marginal Fate of Irrigation Water with Closed Forms from the van Genuchten-Mualem Parameters): every figure of the paper, regenerated by one file.

Run:   python3 Paper4_all_figures.py [WORKDIR]          (default WORKDIR = ./work_paper4)
Needs: Python 3.13 and the packages of Manuscripts/reproducibility/requirements.txt.
Reads: the archived Daisy ensemble (Manuscripts/reproducibility/data) and the archived results
       (Manuscripts/results). Writes only inside WORKDIR; nothing in the repository is changed.

What it does, in order:
  1. builds a working copy of the folder layout the figure scripts expect inside WORKDIR;
  2. rebuilds the data table from the ensemble (make_data.py) when the paper needs it;
  3. runs the figure scripts of this paper one by one, each in its own process, and keeps the log;
  4. lists every figure file that was written and the script that wrote it.

Figure scripts of this paper (in the order they run):
  p4_concept.py          figure 1 concept
  p4_reach.py            figures 2 to 5 reach and marginal fate
  p4_exact.py            exact curves
  p4_callouts.py         annotation marks
  p4_soft_callouts.py    soft annotation marks
"""
import os, sys, shutil, subprocess, time, glob

KEY = "paper4"
NEEDS_DATA = False
STEPS = [('analysis', 'p4_concept', 'figure 1 concept'), ('analysis', 'p4_reach', 'figures 2 to 5 reach and marginal fate'), ('analysis', 'p4_exact', 'exact curves'), ('analysis', 'p4_callouts', 'annotation marks'), ('analysis', 'p4_soft_callouts', 'soft annotation marks')]          # (folder, script, what it makes)
COPY_RESULTS_TO_OUT = False

HERE = os.path.dirname(os.path.abspath(__file__))
def find_repo(p):
    while p != os.path.dirname(p):
        if os.path.isdir(os.path.join(p, "Manuscripts", "reproducibility")): return p
        p = os.path.dirname(p)
    sys.exit("run this file from inside the repository (Data/Manuscript_Documents)")
REPO = find_repo(HERE)
REPRO = os.path.join(REPO, "Manuscripts", "reproducibility")
WORK = os.path.abspath(sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.getcwd(), "work_" + KEY))
MS = os.path.join(WORK, "ms")                      # SWAFL_MS of run_all.sh
MIRROR = os.path.join(WORK, "mirror")              # a copy of the repository layout that the scripts write into
for d in (MS + "/out", MS + "/analysis", MS + "/fig/p1", MS + "/fig/p2", MS + "/fig/p3", MS + "/fig/shots"):
    os.makedirs(d, exist_ok=True)
for d in ("analysis", "p456"):
    shutil.copytree(os.path.join(REPRO, d), os.path.join(MIRROR, "Manuscripts", "reproducibility", d), dirs_exist_ok=True)
for f in ("load.py", "make_data.py"):
    shutil.copy(os.path.join(REPRO, f), os.path.join(MIRROR, "Manuscripts", "reproducibility", f))
    shutil.copy(os.path.join(REPRO, f), MS)
for f in glob.glob(os.path.join(REPRO, "analysis", "*.py")): shutil.copy(f, MS + "/analysis")
for f in glob.glob(os.path.join(REPRO, "intermediates", "*")): shutil.copy(f, MS + "/out")
for f in glob.glob(os.path.join(REPO, "Manuscripts", "figures", "shots", "*.png")): shutil.copy(f, MS + "/fig/shots")
dst = os.path.join(MIRROR, "Manuscripts")
shutil.copytree(os.path.join(REPO, "Manuscripts", "results"), os.path.join(dst, "results"), dirs_exist_ok=True)
for sub in ("tex", "figures"):
    os.makedirs(os.path.join(dst, sub), exist_ok=True)
for f in glob.glob(os.path.join(REPO, "Manuscripts", "tex", "*")):
    if os.path.isfile(f): shutil.copy(f, os.path.join(dst, "tex"))
os.makedirs(os.path.join(dst, "figures", "paper4"), exist_ok=True)
for sub in ("p1", "p2", "p3", "p4", "p5", "p6", "paper4"):      # folders that the figure scripts write into
    os.makedirs(os.path.join(dst, "figures", sub), exist_ok=True)
for sub in ("shots_jpg", "annot"):                        # pictures that some figure scripts annotate
    src_dir = os.path.join(REPO, "Manuscripts", "figures", sub)
    if os.path.isdir(src_dir): shutil.copytree(src_dir, os.path.join(dst, "figures", sub), dirs_exist_ok=True)
if COPY_RESULTS_TO_OUT:                              # results of the Node.js verification steps, archived in the repository
    for f in glob.glob(os.path.join(REPO, "Manuscripts", "results", "*")):
        if os.path.isfile(f): shutil.copy(f, MS + "/out")

env = dict(os.environ, SWAFL_MS=MS, PYTHONHASHSEED="0", OMP_NUM_THREADS="1", OPENBLAS_NUM_THREADS="1", MKL_NUM_THREADS="1", MPLBACKEND="Agg")
LOG = os.path.join(WORK, "logs"); os.makedirs(LOG, exist_ok=True)
def run(label, argv, cwd):
    t = time.time()
    with open(os.path.join(LOG, label + ".txt"), "w") as fh:
        r = subprocess.run(argv, stdout=fh, stderr=subprocess.STDOUT, env=env, cwd=cwd)
    print(("ok      " if r.returncode == 0 else "FAILED  ") + label + "  (%.0f s)" % (time.time() - t), flush=True)
    return r.returncode == 0

failed = 0
if NEEDS_DATA:
    failed += not run("make_data", [sys.executable, os.path.join(REPRO, "make_data.py")], MS)
if not os.path.exists(os.path.join(MIRROR, "Data")):          # the scripts that find the repository by their own location read Data/ from the mirror
    try: os.symlink(os.path.join(REPO, "Data"), os.path.join(MIRROR, "Data"), target_is_directory=True)
    except OSError: shutil.copytree(os.path.join(REPO, "Data", "Comprehensive_Summary"), os.path.join(MIRROR, "Data", "Comprehensive_Summary"))
for folder, script, what in STEPS:
    mirror_path = os.path.join(MIRROR, "Manuscripts", "reproducibility", folder, script + ".py")
    src = open(mirror_path, encoding="utf8", errors="ignore").read()
    if "'../../..'" in src or '"../../.."' in src:                  # these scripts locate the repository from their own folder: run the copy in the mirror
        path, cwd = mirror_path, os.path.dirname(mirror_path)
    elif folder == "analysis":                                       # these scripts read and write inside SWAFL_MS
        path, cwd = os.path.join(MS, "analysis", script + ".py"), MS
    else:
        path, cwd = mirror_path, os.path.dirname(mirror_path)
    failed += not run(script, [sys.executable, path], cwd)

print("\nFigure files written (inside %s):" % WORK)
n = 0
for root in (MS + "/fig", MIRROR + "/Manuscripts/figures"):
    for f in sorted(glob.glob(root + "/**/*", recursive=True)):
        if os.path.isfile(f) and f.lower().endswith((".png", ".pdf", ".svg")) and not any(x in f for x in ("/shots/", "/shots_jpg/", "/annot/")):
            print("  " + os.path.relpath(f, WORK)); n += 1
print("%d figure files, %d script(s) failed. Logs: %s" % (n, failed, LOG))
sys.exit(1 if failed else 0)
